<?php require '../includes/db.php';require '../includes/functions.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$em=trim($_POST['email']??'');$pw=$_POST['password']??'';$s=$conn->prepare('SELECT id,name,password,role FROM users WHERE email=?');$s->bind_param('s',$em);$s->execute();$u=$s->get_result()->fetch_assoc();if($u&&password_verify($pw,$u['password'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['name']=$u['name'];$_SESSION['role']=$u['role'];header('Location: /PHP_Online_Bookstore_21_Practicals/');exit;}else $err='Invalid login details.';}$page_title='Login';include '../includes/header.php';?><div class="formbox"><h1>Login</h1><?php if(isset($_GET['new'])):?><p class="notice">Registration successful. Login now.</p><?php endif;?><?php if($err):?><p class="notice error"><?=e($err)?></p><?php endif;?><form method="post" data-validate><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><button class="btn">Login</button></form></div><?php include '../includes/footer.php';?>
